package com.review.smart\n\nimport android.content.Context\nimport android.content.Intent\nimport android.os.Build\nimport android.provider.Settings\nimport android.widget.Toast\nimport kotlinx.coroutines.Dispatchers\nimport kotlinx.coroutines.launch\nimport kotlinx.coroutines.withContext\nimport org.json.JSONObject\nimport java.net.HttpURLConnection\nimport java.net.URL\nimport androidx.activity.compose.rememberLauncherForActivityResult\nimport androidx.activity.result.contract.ActivityResultContracts\nimport androidx.compose.foundation.background\nimport androidx.compose.foundation.clickable\nimport androidx.compose.foundation.horizontalScroll\nimport androidx.compose.foundation.layout.*\nimport androidx.compose.foundation.lazy.LazyColumn\nimport androidx.compose.foundation.lazy.items\nimport androidx.compose.foundation.rememberScrollState\nimport androidx.compose.material.icons.Icons\nimport androidx.compose.material.icons.filled.*\nimport androidx.compose.material3.*\nimport androidx.compose.runtime.*\nimport androidx.compose.ui.Alignment\nimport androidx.compose.ui.Modifier\nimport androidx.compose.ui.graphics.Color\nimport androidx.compose.ui.platform.LocalContext\nimport androidx.compose.ui.text.font.FontWeight\nimport androidx.compose.ui.text.input.TextFieldValue\nimport androidx.compose.ui.unit.dp\nimport androidx.compose.ui.unit.sp\nimport java.util.*\n\nprivate val Bg=Color(0xFF050806); private val Card=Color(0xFF0B120E); private val Card2=Color(0xFF101A15); private val Green=Color(0xFF38D39A); private val Lime=Color(0xFFC8E888); private val Muted=Color(0xFF91A39A)\nprivate val NavItems=listOf("الرئيسية","المهام","Review Agent","التحليلات","الأهداف","تطوير الذات","التقويم","الإعدادات")\n\n@Composable fun ReviewApp(){\n val ctx=LocalContext.current; val repo=remember{ReviewRepository(ctx)}; var tab by remember{mutableStateOf(0)}; var refresh by remember{mutableIntStateOf(0)}; refresh\n MaterialTheme(colorScheme=darkColorScheme(primary=Green,secondary=Lime,background=Bg,surface=Card,onSurface=Color(0xFFE8F0EA),onBackground=Color.White)){\n  CompositionLocalProvider(LocalLayoutDirection provides androidx.compose.ui.unit.LayoutDirection.Rtl){\n   Scaffold(containerColor=Bg,bottomBar={BottomNav(tab){tab=it}}){pad->\n    Column(Modifier.fillMaxSize().padding(pad)){TopBar(repo){tab=7}; when(tab){0->Dashboard(repo){refresh++};1->Tasks(repo){refresh++};2->AI(repo){refresh++};3->Analytics(repo);4->Goals(repo){refresh++};5->SelfDev(repo){refresh++};6->Calendar(repo);7->Settings(repo)}}\n   }\n  }\n }\n}\n\n@Composable fun TopBar(repo:ReviewRepository,onSettings:()->Unit){Row(Modifier.fillMaxWidth().padding(horizontal=18.dp,vertical=14.dp),horizontalArrangement=Arrangement.SpaceBetween,verticalAlignment=Alignment.CenterVertically){Column{Text("Review",fontSize=24.sp,fontWeight=FontWeight.Black,color=Lime);Text("نظام المراجعة الذكي",fontSize=11.sp,color=Muted)};Row(verticalAlignment=Alignment.CenterVertically){Text("🔥 ${repo.streak}",color=Lime,fontWeight=FontWeight.Bold);Spacer(Modifier.width(14.dp));Text("⭐ ${repo.xp}",color=Green,fontWeight=FontWeight.Bold);IconButton(onClick=onSettings){Icon(Icons.Default.AccountCircle,"الحساب",tint=Color.White)}}}}\n\n@Composable fun BottomNav(selected:Int,onSelect:(Int)->Unit){NavigationBar(containerColor=Color(0xFF080D0A)){val ids=listOf(0,1,2,3,4,7);val icons=listOf(Icons.Default.Home,Icons.Default.CheckCircle,Icons.Default.Psychology,Icons.Default.Insights,Icons.Default.Flag,Icons.Default.Settings);ids.forEachIndexed{i,id->NavigationBarItem(selected==id,onClick={onSelect(id)},icon={Icon(icons[i],null)},label={Text(NavItems[id],fontSize=9.sp)})}}}\n\n@Composable fun SurfaceCard(modifier:Modifier=Modifier,content:@Composable ColumnScope.()->Unit){Card(modifier,colors=CardDefaults.cardColors(containerColor=Card),border=androidx.compose.foundation.BorderStroke(1.dp,Color(0x2238D39A))){Column(Modifier.padding(16.dp),content=content)}}\n@Composable fun SectionTitle(t:String){Text(t,fontSize=18.sp,fontWeight=FontWeight.Bold,modifier=Modifier.padding(vertical=10.dp))}\n@Composable fun Stat(label:String,value:String){SurfaceCard(Modifier.width(120.dp)){Text(value,fontSize=24.sp,fontWeight=FontWeight.Bold,color=Lime);Text(label,color=Muted,fontSize=11.sp)}}\n\n@Composable fun Dashboard(repo:ReviewRepository,onChange:()->Unit){val due=repo.tasks.filter(::isDue); val total=repo.tasks.count{!it.deleted};val done=total-due.size;val pct=if(total==0)0 else (done*100/total);Column(Modifier.fillMaxSize().padding(horizontal=16.dp).verticalScroll(rememberScrollState())){SurfaceCard(Modifier.fillMaxWidth()){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Column{Text("المراجعة اليومية",fontSize=22.sp,fontWeight=FontWeight.Bold);Text("أهلاً بك، مستعد لمراجعة اليوم؟",color=Muted)};Text("🔥 ${repo.streak} يوم",color=Lime,fontWeight=FontWeight.Bold)};Spacer(Modifier.height(18.dp));LinearProgressIndicator({pct/100f},Modifier.fillMaxWidth(),color=Green,trackColor=Card2);Spacer(Modifier.height(8.dp));Text("$pct% • ${due.size} بطاقة متبقية من $total",color=Muted);Spacer(Modifier.height(12.dp));TextButton(onClick={if(due.isNotEmpty()){repo.review(due.first(),3);onChange()}}){Text(if(due.isEmpty())"لا توجد مراجعات مستحقة" else "ابدأ المراجعة الآن ←")}};Spacer(Modifier.height(12.dp));Row(Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(10.dp)){Stat("حزم البطاقات",repo.folders.size.toString());Stat("البطاقات المحفوظة",repo.tasks.count{!it.deleted}.toString());Stat("الاستمرارية",repo.streak.toString())};SectionTitle("مراجعات اليوم");if(due.isEmpty())EmptyCard("أحسنت! لا توجد بطاقات مستحقة الآن.") else due.take(8).forEach{ReviewCard(repo,it,onChange)};Spacer(Modifier.height(20.dp))}}\n\n@Composable fun ReviewCard(repo:ReviewRepository,t:ReviewTask,onChange:()->Unit){var show by remember{mutableStateOf(false)};SurfaceCard(Modifier.fillMaxWidth()){Text(t.title,fontWeight=FontWeight.Bold,fontSize=16.sp);Text("${t.folder} • استحقاق ${fmtDate(t.due)}",color=Muted,fontSize=11.sp);if(show){Spacer(Modifier.height(10.dp));Text(t.answer.ifBlank{"لا توجد إجابة محفوظة."});Spacer(Modifier.height(10.dp));Row(horizontalArrangement=Arrangement.spacedBy(6.dp)){listOf(1 to "مرة أخرى",2 to "صعب",3 to "جيد",4 to "سهل").forEach{(r,s)->Button(onClick={repo.review(t,r);show=false;onChange()}){Text(s,fontSize=11.sp)}}}}else TextButton(onClick={show=true}){Text("إظهار الإجابة")}}}\n@Composable fun EmptyCard(t:String){SurfaceCard(Modifier.fillMaxWidth()){Text(t,color=Muted)}}\n\n@Composable fun Tasks(repo:ReviewRepository,onChange:()->Unit){var q by remember{mutableStateOf("")};var showAdd by remember{mutableStateOf(false)};var selectedFolder by remember{mutableStateOf("كل")};val list=repo.tasks.filter{!it.deleted&&(q.isBlank()||it.title.contains(q,true))&&(selectedFolder=="كل"||it.folder==selectedFolder)};Column(Modifier.fillMaxSize()){Row(Modifier.padding(16.dp),verticalAlignment=Alignment.CenterVertically){OutlinedTextField(q,{q=it},Modifier.weight(1f),placeholder={Text("ابحث في مهامك...")},singleLine=true);IconButton(onClick={showAdd=true}){Icon(Icons.Default.Add,"إضافة")}};Row(Modifier.horizontalScroll(rememberScrollState()).padding(horizontal=16.dp),horizontalArrangement=Arrangement.spacedBy(8.dp)){listOf("كل")+repo.folders.map{it.name}.forEach{FilterChip(selectedFolder==it,onClick={selectedFolder=it},label={Text(it)})}};LazyColumn(Modifier.fillMaxSize().padding(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){item{SectionTitle("كل المهام")};items(list){TaskRow(repo,it,onChange)};item{SectionTitle("سلة المحذوفات")};items(repo.tasks.filter{it.deleted}){TrashRow(repo,it,onChange)}}};if(showAdd)TaskDialog(repo,{showAdd=false;onChange()})}\n\n@Composable fun TaskRow(repo:ReviewRepository,t:ReviewTask,onChange:()->Unit){SurfaceCard(Modifier.fillMaxWidth()){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Column(Modifier.weight(1f)){Text(t.title,fontWeight=FontWeight.Bold);Text("${t.folder} • ${if(isDue(t))"مستحق الآن" else "التالي: ${fmtDate(t.due)}"}",color=Muted,fontSize=11.sp)};IconButton(onClick={repo.deleteTask(t.id);onChange()}){Icon(Icons.Default.Delete,"حذف",tint=Color(0xFFFF8A80))}};if(t.answer.isNotBlank())Text(t.answer,color=Muted,maxLines=2,fontSize=12.sp)}}\n@Composable fun TrashRow(repo:ReviewRepository,t:ReviewTask,onChange:()->Unit){SurfaceCard(Modifier.fillMaxWidth()){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text(t.title);Row{TextButton(onClick={repo.restore(t.id);onChange()}){Text("استعادة")};TextButton(onClick={repo.purge(t.id);onChange()}){Text("حذف نهائي",color=Color(0xFFFF8A80))}}}}}\n\n@Composable fun TaskDialog(repo:ReviewRepository,onClose:()->Unit){var title by remember{mutableStateOf("")};var answer by remember{mutableStateOf("")};var folder by remember{mutableStateOf("عام")};AlertDialog(onDismissRequest=onClose,title={Text("إضافة مهمة")},text={Column(verticalArrangement=Arrangement.spacedBy(10.dp)){OutlinedTextField(title,{title=it},label={Text("اسم المهمة")});OutlinedTextField(answer,{answer=it},label={Text("الإجابة/الملاحظات")});Text("المجلد");Row(Modifier.horizontalScroll(rememberScrollState())){repo.folders.forEach{f->FilterChip(folder==f.name,{folder=f.name},label={Text(f.name)},modifier=Modifier.padding(end=6.dp))}}}},confirmButton={Button(enabled=title.isNotBlank(),onClick={repo.addTask(ReviewTask(title=title,answer=answer,folder=folder));onClose()}){Text("حفظ")}},dismissButton={TextButton(onClick=onClose){Text("إلغاء")}})}\n\n@Composable fun AI(repo:ReviewRepository,onChange:()->Unit){var input by remember{mutableStateOf("")};var mode by remember{mutableStateOf(0)};var lesson by remember{mutableStateOf("")};Column(Modifier.fillMaxSize()){Row(Modifier.fillMaxWidth().padding(16.dp),horizontalArrangement=Arrangement.SpaceBetween,verticalAlignment=Alignment.CenterVertically){Column{Text("Review Agent",fontSize=22.sp,fontWeight=FontWeight.Bold);Text("العقل المركزي · محلي",color=Muted,fontSize=11.sp)};TextButton(onClick={mode=1}){Text(if(mode==0)"🧠 مولد البطاقات" else "💬 الدردشة")}};if(mode==1){Column(Modifier.fillMaxSize().padding(16.dp)){Text("مولد بطاقات المراجعة الذكي",fontSize=20.sp,fontWeight=FontWeight.Bold);Text("الصق نص الدرس وسأحوّله إلى أسئلة وأجوبة.",color=Muted);Spacer(Modifier.height(10.dp));OutlinedTextField(lesson,{lesson=it},Modifier.fillMaxWidth().weight(1f),placeholder={Text("نص الدرس...")});Button(onClick={generateCards(repo,lesson);lesson="";onChange()},enabled=lesson.isNotBlank(),modifier=Modifier.fillMaxWidth()){Text("إنشاء بطاقات وإضافتها للمراجعة")}}}else{Column(Modifier.fillMaxSize()){ChatView(repo,input,{input=it},onChange, Modifier.weight(1f))}}}}\nfun generateCards(repo:ReviewRepository,text:String){val sentences=text.split(Regex("[.!؟\\n]" )).map{it.trim()}.filter{it.length>20}.take(10);sentences.forEachIndexed{i,s->repo.addTask(ReviewTask(title="مراجعة ${i+1}: ${s.take(55)}",answer=s,folder="AI"))}}\n@Composable fun ChatView(repo:ReviewRepository,input:String,setInput:(String)->Unit,onChange:()->Unit,modifier:Modifier=Modifier){\n val scope=rememberCoroutineScope(); var loading by remember{mutableStateOf(false)}\n Column(modifier){\n  LazyColumn(Modifier.weight(1f).fillMaxWidth().padding(horizontal=16.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){\n   if(repo.chats.isEmpty())item{SurfaceCard{Text("مرحباً بك 👋",fontSize=24.sp,fontWeight=FontWeight.Bold);Text("أنا Review Agent. أقرأ بيانات التطبيق المحلية وأحللها قبل أن أجيبك.",color=Muted)}}\n   items(repo.chats){m->SurfaceCard(Modifier.fillMaxWidth()){Text(if(m.role=="user")"أنت" else "Review Agent",color=Green,fontWeight=FontWeight.Bold);Text(m.text)}}\n   if(loading)item{Text("Review Agent يكتب...",color=Muted)}\n  }\n  Row(Modifier.fillMaxWidth().padding(12.dp),verticalAlignment=Alignment.CenterVertically){\n   OutlinedTextField(input,setInput,Modifier.weight(1f),placeholder={Text("اكتب رسالتك...")},singleLine=true)\n   IconButton(enabled=!loading,onClick={if(input.isNotBlank()){val q=input;repo.addChat(ChatMessage("user",q));setInput("");onChange();loading=true;scope.launch{val answer=withContext(Dispatchers.IO){remoteAI(repo,q)};repo.addChat(ChatMessage("assistant",answer));loading=false;onChange()}}}){Icon(Icons.Default.Send,"إرسال")}\n  }\n }\n}\nfun remoteAI(repo:ReviewRepository,q:String):String{\n return try {\n  val context="حالة التطبيق: ${repo.tasks.count{!it.deleted}} بطاقة، ${repo.tasks.count(::isDue)} مستحقة، XP=${repo.xp}، أهداف=${repo.goals.count{!it.completed}}. سؤال المستخدم: $q"\n  val c=URL("https://review-server-nvla.onrender.com/api/ai").openConnection() as HttpURLConnection\n  c.requestMethod="POST"; c.connectTimeout=10000; c.readTimeout=60000; c.doOutput=true; c.setRequestProperty("Content-Type","application/json")\n  c.outputStream.use{it.write(JSONObject().put("message",context).toString().toByteArray())}\n  val raw=(if(c.responseCode in 200..299)c.inputStream else c.errorStream).bufferedReader().use{it.readText()}\n  val reply=JSONObject(raw).optString("reply")\n  if(reply.isNotBlank()) reply else localAI(repo,q)\n }catch(_:Exception){localAI(repo,q)}\n}\n\nfun localAI(repo:ReviewRepository,q:String):String{val due=repo.tasks.count(::isDue);val total=repo.tasks.count{!it.deleted};return when{q.contains("مستحق")||q.contains("اليوم")->"لديك $due بطاقة مستحقة الآن من أصل $total. أنصح بالبدء بالأصعب ثم متابعة البطاقات السهلة.";q.contains("إحص")||q.contains("مستوى")->"XP: ${repo.xp}، الاستمرارية: ${repo.streak} يوم، وعدد البطاقات: $total.";q.contains("بطاق")||q.contains("مراج")&&q.contains("كيف")->"المراجعة المتباعدة تعيد البطاقة في فواصل متزايدة، ويمكنك تقييمها: مرة أخرى، صعب، جيد، سهل.";else->"أستطيع تحليل مهامك ومراجعاتك محليًا. جرّب سؤالي عن المراجعات المستحقة، المستوى، XP أو البطاقات."}}\n\n@Composable fun Analytics(repo:ReviewRepository){val active=repo.tasks.filter{!it.deleted};val reviewed=active.count{it.reps>0};val due=active.count(::isDue);val avgEase=if(active.isEmpty())0 else (active.sumOf{it.ease}/active.size*100).toInt();Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(16.dp)){SectionTitle("متابعة المستوى");Row(Modifier.horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(10.dp)){Stat("إجمالي المهام",active.size.toString());Stat("مراجعات مكتملة",reviewed.toString());Stat("مستحق",due.toString());Stat("قوة الذاكرة", "$avgEase%")};Spacer(Modifier.height(12.dp));SurfaceCard(Modifier.fillMaxWidth()){Text("التقدم",fontWeight=FontWeight.Bold);Spacer(Modifier.height(12.dp));LinearProgressIndicator(if(active.isEmpty())0f else reviewed.toFloat()/active.size,Modifier.fillMaxWidth(),color=Green);Text("${if(active.isEmpty())0 else reviewed*100/active.size}% مراجعات مكتملة",color=Muted)};SurfaceCard(Modifier.fillMaxWidth()){Text("Review Engine",fontWeight=FontWeight.Bold);Text("متوسط خطر النسيان: ${if(active.isEmpty())0 else due*100/active.size}%",color=Muted);Text("متوسط قوة الذاكرة: $avgEase%",color=Muted);Text("المراجعات المتأخرة: $due",color=Muted)};SectionTitle("توزيع الصعوبة");active.groupBy{it.difficulty}.forEach{(d,ls)->Text("${"★".repeat(3-d.coerceIn(1,3))} مستوى $d — ${ls.size} بطاقة",color=Muted)}}}\n\n@Composable fun Goals(repo:ReviewRepository,onChange:()->Unit){var add by remember{mutableStateOf(false)};Column(Modifier.fillMaxSize().padding(16.dp)){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween,verticalAlignment=Alignment.CenterVertically){SectionTitle("الأهداف");Button(onClick={add=true}){Text("هدف جديد")}};LazyColumn(verticalArrangement=Arrangement.spacedBy(10.dp)){items(repo.goals){g->SurfaceCard(Modifier.fillMaxWidth()){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Column{Text(g.title,fontWeight=FontWeight.Bold);Text(g.message,color=Muted);Text("حتى ${fmtDate(g.end)}",color=Muted,fontSize=11.sp)};Checkbox(g.completed,{repo.toggleGoal(g.id);onChange()})};TextButton(onClick={repo.deleteGoal(g.id);onChange()}){Text("حذف",color=Color(0xFFFF8A80))}}}}};if(add)GoalDialog(repo,{add=false;onChange()})}}\n@Composable fun GoalDialog(repo:ReviewRepository,onClose:()->Unit){var title by remember{mutableStateOf("")};var msg by remember{mutableStateOf("")};AlertDialog(onDismissRequest=onClose,title={Text("إنشاء هدف")},text={Column(verticalArrangement=Arrangement.spacedBy(10.dp)){OutlinedTextField(title,{title=it},label={Text("العنوان")});OutlinedTextField(msg,{msg=it},label={Text("رسالة الهدف")})}},confirmButton={Button(enabled=title.isNotBlank(),onClick={repo.addGoal(Goal(title=title,message=msg));onClose()}){Text("حفظ")}},dismissButton={TextButton(onClick=onClose){Text("إلغاء")}})}\n\n@Composable fun SelfDev(repo:ReviewRepository,onChange:()->Unit){val list=repo.tasks.filter{it.selfDev&&!it.deleted};Column(Modifier.fillMaxSize().padding(16.dp)){SectionTitle("تطوير الذات");Text("مهامك التي تساعدك على بناء عادات ومهارات أفضل.",color=Muted);Spacer(Modifier.height(10.dp));if(list.isEmpty())EmptyCard("لا توجد مهام تطوير ذات بعد.");list.forEach{TaskRow(repo,it,onChange)}}}\n\n@Composable fun Calendar(repo:ReviewRepository){var month by remember{mutableStateOf(Calendar.getInstance())};val cal=month.clone() as Calendar;cal.set(Calendar.DAY_OF_MONTH,1);val first=cal.get(Calendar.DAY_OF_WEEK)-1;val days=cal.getActualMaximum(Calendar.DAY_OF_MONTH);Column(Modifier.fillMaxSize().padding(16.dp)){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween,verticalAlignment=Alignment.CenterVertically){IconButton(onClick={month=(month.clone() as Calendar).apply{add(Calendar.MONTH,-1)}}){Icon(Icons.Default.ChevronRight,"السابق")};Text("${month.get(Calendar.YEAR)} / ${month.get(Calendar.MONTH)+1}",fontWeight=FontWeight.Bold);IconButton(onClick={month=(month.clone() as Calendar).apply{add(Calendar.MONTH,1)}}){Icon(Icons.Default.ChevronLeft,"التالي")}};Row(Modifier.fillMaxWidth()){listOf("أح","إث","ثل","أر","خم","جم","سب").forEach{Text(it,Modifier.weight(1f),color=Muted,fontSize=11.sp)}};Column{var d=1;repeat(6){Row(Modifier.fillMaxWidth()){repeat(7){if((it+1)<first||d>days)Box(Modifier.weight(1f).height(52.dp))else{val day=d++;val has=repo.tasks.any{t->!t.deleted&&Calendar.getInstance().apply{timeInMillis=t.due}.get(Calendar.DAY_OF_MONTH)==day&&Calendar.getInstance().apply{timeInMillis=t.due}.get(Calendar.MONTH)==month.get(Calendar.MONTH)};Box(Modifier.weight(1f).height(52.dp).padding(2.dp).background(if(has)Color(0x2238D39A) else Card)){Text(day.toString(),Modifier.padding(5.dp),fontWeight=FontWeight.Bold);if(has)Text("•",Modifier.align(Alignment.BottomCenter),color=Green)}}}}}}}}\n\n@Composable fun Settings(repo:ReviewRepository){val ctx=LocalContext.current;val create=rememberLauncherForActivityResult(ActivityResultContracts.CreateDocument("application/json")){uri->if(uri!=null)ctx.contentResolver.openOutputStream(uri)?.bufferedWriter()?.use{it.write(repo.backup())}};val open=rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()){uri->if(uri!=null)try{val raw=ctx.contentResolver.openInputStream(uri)?.bufferedReader()?.readText()?:("");repo.restoreJson(raw);Toast.makeText(ctx,"تم استيراد النسخة الاحتياطية",Toast.LENGTH_SHORT).show()}catch(e:Exception){Toast.makeText(ctx,"ملف النسخة الاحتياطية غير صالح",Toast.LENGTH_SHORT).show()}};Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(16.dp)){SectionTitle("الإعدادات");SurfaceCard(Modifier.fillMaxWidth()){Text("الحساب والبيانات",fontWeight=FontWeight.Bold);Text("بياناتك المحلية محفوظة على الجهاز.",color=Muted);Spacer(Modifier.height(12.dp));Button(onClick={create.launch("review-backup.json")},modifier=Modifier.fillMaxWidth()){Text("تصدير نسخة احتياطية")};TextButton(onClick={open.launch(arrayOf("application/json"))},modifier=Modifier.fillMaxWidth()){Text("استيراد نسخة احتياطية")}};Spacer(Modifier.height(12.dp));SurfaceCard(Modifier.fillMaxWidth()){Text("الإشعارات",fontWeight=FontWeight.Bold);Text("الإشعارات المحلية تعمل عبر AlarmManager. يمكنك ضبط OneSignal عبر ONESIGNAL_APP_ID.",color=Muted);Button(onClick={if(Build.VERSION.SDK_INT>=31){ctx.startActivity(Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM))}},modifier=Modifier.fillMaxWidth()){Text("إعداد المنبهات الدقيقة")}};Spacer(Modifier.height(12.dp));SurfaceCard(Modifier.fillMaxWidth()){Text("عن Review",fontWeight=FontWeight.Bold);Text("نسخة Native Android مكتوبة بالكامل بـ Kotlin وJetpack Compose، بدون WebView.",color=Muted)}}}\n